 dict(kind="eq", icon="✏️", head="हल उदाहरण: तंबू", words="शंक्वाकार तंबू: ऊँचाई 8 मी, आधार की त्रिज्या 6 मी · कितना कपड़ा?", eq="l = √(36 + 64) = 10 मी · वक्र = 3.14 × 6 × 10 = 188.4 m²",
      note="आधार (ज़मीन) पर कपड़ा नहीं → सिर्फ़ वक्र पृष्ठ",
      say="हल उदाहरण। मेले में एक शंक्वाकार तंबू, ऊँचाई आठ मीटर, आधार की त्रिज्या छह मीटर। कितना कपड़ा लगेगा? पहले तिर्यक ऊँचाई, रूट, छत्तीस प्लस चौंसठ, रूट सौ, दस मीटर। ज़मीन पर कपड़ा नहीं, तो सिर्फ़ वक्र पृष्ठ, पाई गुणा छह गुणा दस, लगभग एक सौ अठासी दशमलव चार वर्ग मीटर।"),

 dict(kind="eq", icon="✏️", head="हल उदाहरण: अनाज का ढेर", words="खलिहान में गेहूँ का शंक्वाकार ढेर: व्यास 10.5 मी, ऊँचाई 3 मी", eq="r = 5.25 · आयतन = ⅓ × 22/7 × 5.25 × 5.25 × 3 = 86.625 m³",
      note="बारिश से बचाने को तिरपाल = वक्र पृष्ठ (l = √(5.25² + 3²) ≈ 6.05 मी)",
      say="खलिहान का सवाल। गेहूँ का एक शंक्वाकार ढेर, व्यास साढ़े दस मीटर, ऊँचाई तीन मीटर। आयतन? त्रिज्या पाँच दशमलव दो पाँच। एक तिहाई गुणा बाईस बटा सात गुणा पाँच दशमलव दो पाँच का वर्ग गुणा तीन। एक तिहाई और तीन कट गए। बाईस बटा सात गुणा पाँच दशमलव दो पाँच गुणा पाँच दशमलव दो पाँच, छियासी दशमलव छह दो पाँच घन मीटर। बारिश से बचाने के लिए तिरपाल चाहिए, तो वक्र पृष्ठ निकालना होगा।"),

